head.script:
//
(function () {
  var root = document.documentElement;
  var theme = null;
  var language = null;
  try {
    theme = localStorage.getItem('inoxup-theme');
    language = localStorage.getItem('inoxup-language');
  } catch (error) {}
  if (theme !== 'dark' && theme !== 'light') {
    theme = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  }
  if (language !== 'ar' && language !== 'en' && language !== 'fr') { language = 'fr'; }
  root.setAttribute('data-theme', theme);
  root.setAttribute('data-lang', language);
  root.setAttribute('lang', language);
  root.setAttribute('dir', language === 'ar' ? 'rtl' : 'ltr');
}());
//

head.b:skin:
/* ---------------------------------------------------------
   INOX.UP — Premium Blogger theme
   Palette : graphite, papier minéral et bleu acier.
   --------------------------------------------------------- */
:root {
  --ink: #171d22;
  --ink-2: #232c33;
  --ink-3: #303d46;
  --paper: #f2f4f5;
  --surface: #ffffff;
  --steel: #aab1ab;
  --muted: #676d66;
  --line: #d8dee2;
  --line-dark: rgba(255,255,255,.14);
  --accent: #8fc8ff;
  --accent-dark: #23577b;
  --whatsapp: #10733b;
  --radius: 18px;
  --radius-sm: 10px;
  --shadow: 0 24px 70px rgba(23,29,34,.10);
  --container: 1200px;
  --on-light: #171d22;
  --body-copy: #343a34;
  --soft-accent: #e9f1f7;
  --field-bg: #f8fafb;
  --image-placeholder: #e3e9ed;
  color-scheme: light;
}
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 108px; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--on-light);
  font-family: 'Manrope', Arial, sans-serif;
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body, .widget, .post-body { overflow-wrap: break-word; }
img { max-width: 100%; }
a { color: inherit; }
button, input, select, textarea { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button { color: inherit; }
::selection { background: var(--accent); color: var(--ink); }
:focus-visible { outline: 3px solid var(--accent); outline-offset: 4px; }
.container { width: min(var(--container), calc(100% - 48px)); margin-inline: auto; }
.icon { width: 20px; height: 20px; flex: 0 0 auto; display: inline-block; vertical-align: middle; }
.svg-sprite { position: absolute; width: 0; height: 0; overflow: hidden; }
.skip-link { position: fixed; top: 12px; left: 12px; z-index: 9999; padding: 10px 16px; background: var(--accent); color: var(--ink); border-radius: 6px; transform: translateY(-160%); transition: transform .2s; }
.skip-link:focus { transform: translateY(0); }
.scroll-progress { position: fixed; z-index: 1200; top: 0; left: 0; width: 100%; height: 3px; background: var(--accent); transform: scaleX(0); transform-origin: left center; pointer-events: none; }
html[dir='rtl'] .scroll-progress { transform-origin: right center; }
html[data-motion='ready'] [data-reveal], html[data-motion='ready'] [data-reveal-item='true'] { opacity: 0; }
html[data-motion='ready'] [data-reveal='transform'], html[data-motion='ready'] [data-reveal='transform-scale'] { opacity: 1; }
html[data-motion='ready'] [data-reveal].is-visible, html[data-motion='ready'] [data-reveal-item='true'].is-visible { opacity: 1; }
.eyebrow { display: inline-flex; align-items: center; gap: 10px; margin: 0 0 18px; font-size: .72rem; line-height: 1.4; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; }
.eyebrow::before { content: ''; width: 28px; height: 2px; background: currentColor; }
.eyebrow--accent { color: var(--accent); }
.section { padding: 104px 0; }
.section-heading { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(280px, .75fr); gap: 48px; align-items: end; margin-bottom: 48px; }
.section-heading h2 { margin: 0; max-width: 760px; font-size: clamp(2rem, 4vw, 3.35rem); line-height: 1.12; letter-spacing: -.045em; font-weight: 700; }
.section-heading > p { margin: 0 0 4px; color: var(--muted); font-size: .98rem; }
.section-heading--dark > p { color: #b6bdb5; }
.btn { display: inline-flex; min-height: 50px; align-items: center; justify-content: center; gap: 10px; padding: 13px 21px; border: 1px solid transparent; border-radius: 8px; text-decoration: none; font-weight: 700; font-size: .88rem; line-height: 1.3; cursor: pointer; transition: transform .2s ease, background .2s ease, color .2s ease, border-color .2s ease; }
.btn:hover { transform: translateY(-2px); }
.btn--accent { background: var(--accent); color: var(--ink); }
.btn--accent:hover { background: #b9dfff; }
.btn--dark { background: var(--ink); color: #fff; }
.btn--dark:hover { background: var(--ink-3); }
.btn--ghost { border-color: rgba(255,255,255,.35); color: #fff; background: transparent; }
.btn--ghost:hover { border-color: #fff; background: rgba(255,255,255,.07); }
.btn--outline { border-color: var(--line); background: transparent; color: var(--on-light); }
.btn--outline:hover { border-color: var(--on-light); }
.text-link { display: inline-flex; align-items: center; gap: 8px; color: inherit; text-decoration: none; font-size: .82rem; font-weight: 800; }
.text-link .icon { width: 17px; transition: transform .2s ease; }
.text-link:hover .icon { transform: translate(3px,-3px); }

/* Top bar + navigation */
.topbar { background: #11171b; color: #d5dad3; border-bottom: 1px solid var(--line-dark); font-size: .72rem; }
.topbar-inner { min-height: 36px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.topbar p { margin: 0; }
.topbar-status { display: flex; align-items: center; gap: 9px; }
.status-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(143,200,255,.09); }
.topbar-links { display: flex; align-items: center; gap: 22px; }
.topbar a { display: inline-flex; align-items: center; gap: 7px; color: inherit; text-decoration: none; }
.topbar a:hover { color: var(--accent); }
.topbar .icon { width: 14px; height: 14px; }
.site-header { position: sticky; top: 0; z-index: 1000; background: rgba(23,29,34,.96); color: #fff; border-bottom: 1px solid var(--line-dark); backdrop-filter: blur(16px); transition: box-shadow .25s ease; }
.site-header.is-scrolled { box-shadow: 0 12px 35px rgba(0,0,0,.18); }
.navbar { min-height: 78px; display: flex; align-items: center; gap: 32px; position: relative; }
.brand { display: inline-flex; align-items: center; gap: 11px; margin-right: auto; color: #fff; text-decoration: none; }
.brand-mark { width: 40px; height: 40px; display: grid; place-items: center; border: 1px solid rgba(255,255,255,.28); border-radius: 7px; color: var(--accent); }
.brand-mark--logo { overflow: hidden; background: #fff; }
.brand-logo-image { display: block; width: 100%; height: 100%; padding: 2px; object-fit: contain; border-radius: 6px; background: #fff; }
.brand-logo-fallback { display: none; }
.brand-mark svg { width: 29px; height: 29px; }
.brand-copy { display: grid; line-height: 1; gap: 6px; }
.brand-name { font-size: 1.12rem; letter-spacing: .06em; font-weight: 800; }
.brand-name span { color: var(--accent); }
.brand-tagline { color: #9ea69e; font-size: .52rem; letter-spacing: .15em; text-transform: uppercase; font-weight: 700; }
.site-nav { display: flex; align-items: center; gap: 28px; }
.site-nav a { position: relative; color: #c6ccc5; text-decoration: none; font-size: .78rem; font-weight: 700; }
.site-nav a::after { content: ''; position: absolute; left: 0; right: 100%; bottom: -8px; height: 2px; background: var(--accent); transition: right .2s ease; }
.site-nav a:hover { color: #fff; }
.site-nav a:hover::after { right: 0; }
.header-cta { min-height: 42px; padding: 10px 16px; font-size: .76rem; }
.preferences { display: flex; align-items: center; gap: 7px; }
.theme-toggle { width: 40px; height: 40px; display: inline-grid; place-items: center; padding: 0; border: 1px solid var(--line-dark); border-radius: 8px; background: transparent; color: #fff; cursor: pointer; }
.theme-toggle:hover { border-color: var(--accent); color: var(--accent); }
.theme-toggle .icon { width: 18px; height: 18px; }
.theme-icon--moon { display: none; }
:root[data-theme='dark'] .theme-icon--sun { display: none; }
:root[data-theme='dark'] .theme-icon--moon { display: block; }
.language-select { width: 58px; height: 40px; padding: 0 7px; border: 1px solid var(--line-dark); border-radius: 8px; background: var(--ink); color: #fff; font-size: .68rem; font-weight: 800; cursor: pointer; }
.language-select option { background: var(--ink); color: #fff; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.nav-toggle { display: none; width: 44px; height: 44px; border: 1px solid var(--line-dark); border-radius: 8px; background: transparent; cursor: pointer; align-items: center; justify-content: center; }
.nav-toggle-box { width: 20px; height: 15px; position: relative; }
.nav-toggle-box span { position: absolute; left: 0; width: 100%; height: 2px; background: #fff; transition: transform .2s, top .2s, opacity .2s; }
.nav-toggle-box span:first-child { top: 1px; }
.nav-toggle-box span:nth-child(2) { top: 7px; }
.nav-toggle-box span:last-child { top: 13px; }
.nav-open .nav-toggle-box span:first-child { top: 7px; transform: rotate(45deg); }
.nav-open .nav-toggle-box span:nth-child(2) { opacity: 0; }
.nav-open .nav-toggle-box span:last-child { top: 7px; transform: rotate(-45deg); }

/* Hero */
.hero { position: relative; overflow: hidden; background: var(--ink); color: #fff; }
.hero::before { content: ''; position: absolute; inset: 0; pointer-events: none; opacity: .18; background-image: linear-gradient(rgba(255,255,255,.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.05) 1px, transparent 1px); background-size: 72px 72px; mask-image: linear-gradient(to right, #000, transparent 68%); }
.hero-inner { min-height: 680px; display: grid; grid-template-columns: minmax(0, .93fr) minmax(420px, 1.07fr); gap: 68px; align-items: center; padding-top: 72px; padding-bottom: 72px; position: relative; }
.hero-copy { position: relative; z-index: 2; }
.hero h1 { margin: 0 0 24px; max-width: 650px; font-size: clamp(3rem, 5.4vw, 5.15rem); font-weight: 600; line-height: 1.01; letter-spacing: -.065em; }
.hero h1 span { color: var(--accent); }
.hero-lead { max-width: 580px; margin: 0; color: #bdc4bc; font-size: 1rem; line-height: 1.85; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }
.hero-assurances { display: flex; flex-wrap: wrap; gap: 18px 26px; padding: 0; margin: 36px 0 0; list-style: none; color: #d9ded8; font-size: .74rem; font-weight: 600; }
.hero-assurances li { display: flex; align-items: center; gap: 7px; }
.hero-assurances .icon { width: 16px; height: 16px; color: var(--accent); }
.hero-visual { position: relative; min-width: 0; padding: 0 0 30px 28px; }
.hero-visual::before { content: ''; position: absolute; left: 0; bottom: 0; width: 58%; height: 62%; border: 1px solid rgba(143,200,255,.4); border-radius: 12px; }
.hero-photo { position: relative; margin: 0; border-radius: 12px; overflow: hidden; box-shadow: 0 30px 80px rgba(0,0,0,.34); }
.hero-photo::after { content: ''; position: absolute; inset: 0; background: linear-gradient(to top, rgba(15,18,15,.52), transparent 42%); pointer-events: none; }
.hero-photo img { display: block; width: 100%; height: 500px; object-fit: cover; transition: transform 1s cubic-bezier(.2,.7,.2,1); }
.hero-photo:hover img { transform: scale(1.025); }
.hero-photo figcaption { position: absolute; z-index: 1; bottom: 20px; left: 22px; display: flex; align-items: center; gap: 10px; font-size: .66rem; letter-spacing: .14em; font-weight: 800; }
.hero-photo figcaption::before { content: ''; width: 24px; height: 2px; background: var(--accent); }
.hero-note { position: absolute; z-index: 3; right: -18px; bottom: 0; width: 210px; padding: 20px; background: var(--accent); color: var(--ink); border-radius: 10px; box-shadow: 0 16px 45px rgba(0,0,0,.2); }
.hero-note .icon { width: 26px; height: 26px; margin-bottom: 18px; }
.hero-note strong { display: block; margin-bottom: 5px; font-size: .9rem; }
.hero-note span { display: block; font-size: .7rem; line-height: 1.55; }
.precision-strip { background: var(--accent); color: var(--ink); }
.precision-grid { display: grid; grid-template-columns: repeat(3, 1fr); }
.precision-item { display: flex; align-items: center; justify-content: center; gap: 14px; min-height: 84px; padding: 18px 28px; border-right: 1px solid rgba(23,29,34,.18); }
.precision-item:last-child { border-right: 0; }
.precision-item .icon { width: 24px; height: 24px; }
.precision-item strong { display: block; font-size: .82rem; }
.precision-item span { display: block; font-size: .67rem; opacity: .7; }

/* Services */
.services-section { background: var(--paper); }
.services-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }
.service-card { position: relative; min-height: 310px; display: flex; flex-direction: column; padding: 30px; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-sm); transition: background .25s ease, color .25s ease, transform .25s ease, box-shadow .25s ease; }
.service-card:hover { background: var(--ink); color: #fff; transform: translateY(-5px); box-shadow: var(--shadow); }
.service-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.service-icon { width: 48px; height: 48px; display: grid; place-items: center; border-radius: 8px; background: var(--soft-accent); color: var(--on-light); transition: background .25s, color .25s; }
.service-icon .icon { width: 25px; height: 25px; }
.service-number { color: var(--muted); font-size: .68rem; letter-spacing: .14em; font-weight: 800; }
.service-card h3 { margin: 28px 0 12px; font-size: 1.16rem; line-height: 1.4; letter-spacing: -.02em; }
.service-card p { margin: 0 0 26px; color: var(--muted); font-size: .82rem; line-height: 1.75; transition: color .25s; }
.service-card .text-link { margin-top: auto; }
.service-card:hover p, .service-card:hover .service-number { color: #b8c0b7; }
.service-card:hover .service-icon { background: var(--accent); color: var(--ink); }
.service-card:hover .text-link { color: var(--accent); }

/* Gallery */
.gallery-section { background: var(--surface); }
.gallery-grid { display: grid; grid-template-columns: repeat(12, 1fr); grid-auto-rows: 230px; gap: 14px; }
.project-card { position: relative; grid-column: span 4; padding: 0; border: 0; border-radius: 10px; overflow: hidden; background: var(--image-placeholder); cursor: zoom-in; text-align: left; }
.project-card:nth-child(1) { grid-column: span 7; grid-row: span 2; }
.project-card:nth-child(2) { grid-column: span 5; }
.project-card:nth-child(3) { grid-column: span 5; }
.project-card:nth-child(4), .project-card:nth-child(5) { grid-column: span 6; }
.project-card img { width: 100%; height: 100%; display: block; object-fit: cover; transition: transform .6s cubic-bezier(.2,.7,.2,1); }
.project-card::after { content: ''; position: absolute; inset: 35% 0 0; background: linear-gradient(to top, rgba(12,15,12,.82), transparent); pointer-events: none; }
.project-card:hover img { transform: scale(1.045); }
.project-caption { position: absolute; z-index: 2; left: 22px; right: 58px; bottom: 19px; color: #fff; }
.project-caption small { display: block; margin-bottom: 4px; color: #dbe7f0; font-size: .59rem; letter-spacing: .13em; text-transform: uppercase; font-weight: 700; }
.project-caption strong { display: block; font-size: .92rem; line-height: 1.4; }
.project-zoom { position: absolute; z-index: 2; right: 18px; bottom: 18px; width: 34px; height: 34px; display: grid; place-items: center; border-radius: 50%; background: var(--accent); color: var(--ink); }
.project-zoom .icon { width: 16px; height: 16px; }
.gallery-note { margin: 18px 0 0; color: var(--muted); font-size: .7rem; }
.social-section { padding: 0 0 104px; background: var(--surface); }
.social-card { display: flex; align-items: center; justify-content: space-between; gap: 36px; padding: 34px 38px; border-radius: 12px; background: var(--accent); color: var(--ink); }
.social-profile { display: flex; align-items: center; gap: 22px; min-width: 0; }
.social-logo { width: 74px; height: 74px; flex: 0 0 auto; border-color: rgba(23,29,34,.18); border-radius: 12px; }
.social-logo .brand-logo-image { border-radius: 10px; }
.social-profile .eyebrow { margin-bottom: 8px; font-size: .62rem; }
.social-profile h2 { margin: 0 0 7px; font-size: clamp(1.35rem, 2.4vw, 2rem); line-height: 1.25; letter-spacing: -.035em; }
.social-profile p:last-child { margin: 0; max-width: 570px; font-size: .75rem; }
.social-actions { display: flex; flex: 0 0 auto; flex-wrap: wrap; gap: 10px; }
.social-actions .btn--outline { border-color: rgba(23,29,34,.3); }
.lightbox { width: min(1060px, calc(100% - 32px)); max-height: 92vh; padding: 0; border: 0; border-radius: 12px; background: var(--ink); color: #fff; box-shadow: 0 35px 100px rgba(0,0,0,.55); overflow: visible; }
.lightbox::backdrop { background: rgba(8,10,8,.86); backdrop-filter: blur(7px); }
.lightbox[open] { animation: lightbox-in .26s cubic-bezier(.2,.7,.2,1); }
@keyframes lightbox-in { from { opacity: 0; transform: translateY(12px) scale(.985); } to { opacity: 1; transform: none; } }
.lightbox img { display: block; width: 100%; max-height: 78vh; object-fit: contain; border-radius: 12px 12px 0 0; }
.lightbox-caption { margin: 0; padding: 14px 20px; font-size: .8rem; }
.lightbox-close { position: absolute; top: -15px; right: -12px; width: 40px; height: 40px; border: 0; border-radius: 50%; background: var(--accent); color: var(--ink); font-size: 1.4rem; cursor: pointer; }

/* Process */
.process-section { background: var(--ink); color: #fff; }
.process-grid { display: grid; grid-template-columns: repeat(4, 1fr); border-top: 1px solid var(--line-dark); }
.process-step { position: relative; padding: 34px 28px 10px 0; }
.process-step:not(:last-child) { margin-right: 28px; }
.process-step::before { content: ''; position: absolute; top: -5px; left: 0; width: 9px; height: 9px; border-radius: 50%; background: var(--accent); }
.process-step::after { content: ''; position: absolute; top: -1px; left: 9px; right: 0; height: 1px; background: var(--accent); opacity: .45; }
.process-step:last-child::after { display: none; }
.process-number { color: var(--accent); font-size: .65rem; font-weight: 800; letter-spacing: .16em; }
.process-step h3 { margin: 18px 0 10px; font-size: 1rem; }
.process-step p { margin: 0; color: #aeb6ad; font-size: .78rem; line-height: 1.75; }

/* Values */
.values-section { padding: 0; background: var(--paper); }
.values-inner { display: grid; grid-template-columns: .9fr 1.1fr; gap: 80px; align-items: center; padding-top: 104px; padding-bottom: 104px; }
.values-copy h2 { margin: 0 0 22px; font-size: clamp(2rem, 3.6vw, 3.2rem); line-height: 1.13; letter-spacing: -.045em; }
.values-copy > p { margin: 0; color: var(--muted); font-size: .9rem; }
.values-copy .btn { margin-top: 28px; }
.values-list { display: grid; gap: 0; }
.value-item { display: grid; grid-template-columns: 46px 1fr; gap: 18px; padding: 25px 0; border-bottom: 1px solid var(--line); }
.value-item:first-child { border-top: 1px solid var(--line); }
.value-icon { width: 42px; height: 42px; display: grid; place-items: center; background: var(--soft-accent); border-radius: 50%; }
.value-item h3 { margin: 0 0 5px; font-size: .92rem; }
.value-item p { margin: 0; color: var(--muted); font-size: .77rem; }

/* FAQ */
.faq-section { background: var(--surface); }
.faq-layout { display: grid; grid-template-columns: .7fr 1.3fr; gap: 80px; align-items: start; }
.faq-intro { position: sticky; top: 120px; }
.faq-intro h2 { margin: 0 0 18px; font-size: clamp(2rem, 3.5vw, 3rem); line-height: 1.15; letter-spacing: -.045em; }
.faq-intro p { color: var(--muted); font-size: .85rem; }
.faq-intro a { color: var(--on-light); font-weight: 800; }
.faq-list { border-top: 1px solid var(--line); }
.faq-item { border-bottom: 1px solid var(--line); }
.faq-item summary { position: relative; padding: 24px 50px 24px 0; list-style: none; cursor: pointer; font-size: .93rem; font-weight: 800; }
.faq-item summary::-webkit-details-marker { display: none; }
.faq-item summary::before, .faq-item summary::after { content: ''; position: absolute; top: 50%; right: 5px; width: 16px; height: 2px; background: var(--on-light); transition: transform .2s; }
.faq-item summary::after { transform: rotate(90deg); }
.faq-item[open] summary::after { transform: rotate(0); }
.faq-item[open] summary { color: var(--accent-dark); }
.faq-answer { padding: 0 44px 24px 0; color: var(--muted); font-size: .82rem; }
.faq-answer p { margin: 0; }

/* Quote form */
.quote-section { position: relative; overflow: hidden; background: var(--ink); color: #fff; }
.quote-section::after { content: 'INOX'; position: absolute; right: -25px; bottom: -110px; color: rgba(255,255,255,.025); font-size: 19rem; line-height: 1; font-weight: 800; letter-spacing: -.08em; pointer-events: none; }
.quote-layout { position: relative; z-index: 1; display: grid; grid-template-columns: .85fr 1.15fr; gap: 90px; align-items: start; }
.quote-copy h2 { margin: 0 0 22px; font-size: clamp(2.25rem, 4.4vw, 4rem); line-height: 1.08; letter-spacing: -.055em; }
.quote-copy > p { color: #b8c0b7; font-size: .88rem; }
.quote-contact { display: grid; gap: 12px; margin-top: 34px; }
.quote-contact a { display: flex; align-items: center; gap: 13px; width: fit-content; color: #fff; text-decoration: none; font-size: .82rem; font-weight: 700; }
.quote-contact a:hover { color: var(--accent); }
.quote-contact .icon { color: var(--accent); }
.quote-form { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; padding: 34px; background: var(--surface); color: var(--on-light); border-radius: 12px; box-shadow: 0 30px 80px rgba(0,0,0,.2); }
.form-field { display: grid; gap: 8px; }
.form-field--full { grid-column: 1 / -1; }
.form-field label { font-size: .7rem; font-weight: 800; }
.form-field label span { color: var(--muted); font-weight: 500; }
.form-field input, .form-field select, .form-field textarea { width: 100%; min-height: 48px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 7px; background: var(--field-bg); color: var(--on-light); font-size: .8rem; outline: none; transition: border-color .2s, box-shadow .2s; }
.form-field textarea { min-height: 112px; resize: vertical; }
.form-field input:focus, .form-field select:focus, .form-field textarea:focus { border-color: #4e83aa; box-shadow: 0 0 0 3px rgba(143,200,255,.35); }
.quote-form .btn { width: 100%; border: 0; }
.form-privacy { grid-column: 1 / -1; margin: -6px 0 0; color: var(--muted); font-size: .63rem; text-align: center; }
.form-status { grid-column: 1 / -1; min-height: 0; margin: 0; color: var(--accent-dark); font-size: .72rem; text-align: center; }

/* Blog / articles */
.journal-section { padding: 96px 0; background: var(--paper); }
.archive-header { padding: 72px 0 50px; background: var(--ink); color: #fff; }
.archive-header h1 { margin: 0; max-width: 850px; font-size: clamp(2.2rem, 5vw, 4.3rem); line-height: 1.1; letter-spacing: -.05em; }
.archive-header p:last-child { margin: 16px 0 0; color: #b9c1b8; }
.blog-posts.post-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 22px; }
.post-grid .post-outer-container { min-width: 0; }
.post-grid .post-outer { height: 100%; }
.post-grid .post { height: 100%; display: flex; flex-direction: column; background: var(--surface); border: 1px solid var(--line); border-radius: 12px; overflow: hidden; transition: transform .25s, box-shadow .25s; }
.post-grid .post:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
.post-card-media { display: block; aspect-ratio: 4 / 3; overflow: hidden; background: var(--image-placeholder); }
.post-card-media img { width: 100%; height: 100%; display: block; object-fit: cover; transition: transform .5s; }
.post:hover .post-card-media img { transform: scale(1.04); }
.post-card-content { display: flex; flex: 1; flex-direction: column; padding: 24px; }
.post-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-bottom: 14px; color: var(--muted); font-size: .65rem; font-weight: 600; }
.post-labels { display: flex; flex-wrap: wrap; gap: 6px; }
.post-labels a { padding: 3px 8px; border-radius: 4px; background: var(--soft-accent); color: var(--accent-dark); text-decoration: none; font-size: .59rem; font-weight: 800; }
.post-title { margin: 0; line-height: 1.35; letter-spacing: -.025em; }
.post-card-content .post-title { font-size: 1.08rem; }
.post-title a { text-decoration: none; }
.post-title a:hover { color: var(--accent-dark); }
.post-excerpt { margin: 13px 0 24px; color: var(--muted); font-size: .77rem; line-height: 1.75; }
.post-card-content > .text-link { margin-top: auto; }
.single-post { max-width: 880px; margin: 0 auto; }
.single-post .post { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; overflow: hidden; }
.post-single-header { padding: 44px 54px 34px; }
.breadcrumbs { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 28px; color: var(--muted); font-size: .68rem; }
.breadcrumbs a { text-decoration: none; font-weight: 700; }
.breadcrumbs a:hover { color: var(--accent-dark); }
.post-single-header .post-title { margin: 10px 0 20px; font-size: clamp(2rem, 5vw, 3.4rem); line-height: 1.15; letter-spacing: -.05em; }
.post-single-image { margin: 0; }
.post-single-image img { display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; max-height: 580px; object-fit: cover; }
.post-body { padding: 44px 54px; color: var(--body-copy); font-size: .98rem; line-height: 1.9; }
.post-body > :first-child { margin-top: 0; }
.post-body > :last-child { margin-bottom: 0; }
.post-body h2, .post-body h3, .post-body h4 { margin: 1.8em 0 .65em; color: var(--on-light); line-height: 1.3; letter-spacing: -.025em; }
.post-body h2 { font-size: 1.65rem; }
.post-body h3 { font-size: 1.3rem; }
.post-body a { color: var(--accent-dark); text-decoration-thickness: 1px; text-underline-offset: 3px; }
.post-body img { height: auto; border-radius: 8px; }
.post-body blockquote { margin: 30px 0; padding: 20px 24px; border-inline-start: 4px solid var(--accent); background: var(--soft-accent); color: var(--on-light); }
.post-body ul, .post-body ol { padding-inline-start: 24px; }
.post-body table { display: block; max-width: 100%; overflow-x: auto; border-collapse: collapse; }
.post-body td, .post-body th { padding: 10px; border: 1px solid var(--line); }
.post-body pre { max-width: 100%; overflow-x: auto; padding: 18px; border-radius: 8px; background: var(--ink); color: #e8ede6; }
.post-body iframe { max-width: 100%; }
.post-labels-footer { padding: 0 54px 40px; }
.article-cta { display: flex; align-items: center; justify-content: space-between; gap: 24px; margin: 0 54px 50px; padding: 25px; border-radius: 10px; background: var(--ink); color: #fff; }
.article-cta strong { display: block; font-size: .95rem; }
.article-cta span { color: #b8c0b7; font-size: .72rem; }
.article-cta .btn { flex: 0 0 auto; }
.blog-pager { display: flex; justify-content: center; flex-wrap: wrap; gap: 10px; margin-top: 38px; }
.blog-pager a { display: inline-flex; padding: 10px 16px; border: 1px solid var(--line); border-radius: 7px; background: var(--surface); text-decoration: none; font-size: .75rem; font-weight: 800; }
.blog-pager a:hover { border-color: var(--on-light); }
.blog-feeds, .post-feeds { margin-top: 28px; color: var(--muted); font-size: .7rem; text-align: center; }
.feed-link { color: inherit; }
.comments { max-width: 880px; margin: 26px auto 0; padding: 32px 42px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); }
.comments .title { margin: 0 0 24px; font-size: 1.25rem; }
.comments .comment { position: relative; padding: 18px 0; border-top: 1px solid var(--line); }
.comments .avatar-image-container { float: left; width: 38px; height: 38px; margin-right: 12px; border-radius: 50%; overflow: hidden; }
.comments .avatar-image-container img { width: 100%; height: 100%; object-fit: cover; }
.comments .comment-block { margin-left: 50px; }
.comments .comment-author { font-size: .75rem; font-weight: 800; }
.comments .comment-body { margin-top: 6px; color: var(--muted); font-size: .8rem; }
.comments .comment-footer, .comments .comment-timestamp { font-size: .63rem; color: var(--muted); }
.comments .comment-form h4 { margin: 22px 0 12px; }
.comments a { color: var(--accent-dark); }
.item-control { float: right; }
.inline-ad { margin: 24px 0; }

/* Footer + floating contact */
.site-footer { background: #11171b; color: #fff; }
.footer-main { display: grid; grid-template-columns: 1.35fr .65fr .8fr; gap: 70px; padding-top: 70px; padding-bottom: 54px; }
.footer-brand > p { max-width: 390px; margin: 22px 0; color: #aeb6ad; font-size: .78rem; }
.social-links { display: flex; gap: 9px; }
.social-links a { width: 38px; height: 38px; display: grid; place-items: center; border: 1px solid var(--line-dark); border-radius: 7px; color: #fff; transition: background .2s, color .2s; }
.social-links a:hover { background: var(--accent); color: var(--ink); }
.social-links .icon { width: 17px; height: 17px; }
.footer-title { margin: 4px 0 20px; color: #f2f5f0; font-size: .72rem; letter-spacing: .12em; text-transform: uppercase; }
.footer-nav { display: grid; gap: 11px; }
.footer-nav a { width: fit-content; color: #aeb6ad; text-decoration: none; font-size: .75rem; }
.footer-nav a:hover { color: var(--accent); }
.footer-contact { display: grid; gap: 13px; }
.footer-contact a, .footer-contact span { display: flex; align-items: flex-start; gap: 10px; color: #aeb6ad; text-decoration: none; font-size: .74rem; }
.footer-contact a:hover { color: var(--accent); }
.footer-contact .icon { width: 16px; height: 16px; margin-top: 3px; color: var(--accent); }
.footer-bottom { min-height: 64px; display: flex; align-items: center; justify-content: space-between; gap: 20px; border-top: 1px solid var(--line-dark); color: #7f887e; font-size: .64rem; }
.footer-bottom p { margin: 0; }
.footer-bottom a { color: #b7c0b5; text-decoration: none; }
.whatsapp-float { position: fixed; z-index: 900; right: 22px; bottom: 22px; display: inline-flex; align-items: center; gap: 9px; min-height: 50px; padding: 13px 18px; border: 1px solid rgba(255,255,255,.35); border-radius: 28px; background: var(--whatsapp); color: #fff; box-shadow: 0 12px 32px rgba(15,80,40,.28); text-decoration: none; font-size: .72rem; font-weight: 800; transition: transform .2s, background .2s; }
.whatsapp-float:hover { transform: translateY(-3px); background: #0b5c2f; }
.whatsapp-float .icon { width: 22px; height: 22px; }

/* Dark mode : surfaces, articles, formulaires et commentaires. */
:root[data-theme='dark'] {
  --paper: #10171c;
  --surface: #1a242b;
  --muted: #a4b1ba;
  --line: #35444e;
  --accent-dark: #8fc8ff;
  --on-light: #eef4f7;
  --body-copy: #c7d1d8;
  --soft-accent: #243945;
  --field-bg: #202d35;
  --image-placeholder: #27353d;
  --shadow: 0 24px 70px rgba(0,0,0,.28);
  color-scheme: dark;
}
input::placeholder, textarea::placeholder { color: var(--muted); opacity: .85; }
:root[data-theme='dark'] .social-card .btn--outline { color: var(--ink); border-color: rgba(23,29,34,.3); }
:root[data-theme='dark'] .social-card .btn--outline:hover { border-color: var(--ink); }

@media (max-width: 1080px) {
  .header-cta { order: 2; margin-inline-start: 4px; }
  .nav-toggle { display: inline-flex; order: 3; }
  .site-nav { position: absolute; top: calc(100% + 1px); left: 0; right: 0; display: grid; gap: 0; max-height: 0; padding: 0 20px; overflow: hidden; visibility: hidden; opacity: 0; background: var(--ink); border: 1px solid var(--line-dark); border-radius: 0 0 10px 10px; transition: max-height .25s, opacity .2s, padding .25s, visibility .25s; }
  .nav-open .site-nav { max-height: 420px; padding: 12px 20px 20px; visibility: visible; opacity: 1; }
  .site-nav a { padding: 12px 0; border-bottom: 1px solid var(--line-dark); font-size: .8rem; }
  .site-nav a:last-child { border-bottom: 0; }
  .site-nav a::after { display: none; }
}
@media (max-width: 1080px) {
  .hero-inner { grid-template-columns: 1fr 1fr; gap: 38px; }
  .hero-photo img { height: 450px; }
  .hero-note { right: 0; }
  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .values-inner, .faq-layout { gap: 50px; }
  .quote-layout { gap: 50px; }
  .blog-posts.post-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 860px) {
  html { scroll-padding-top: 88px; }
  .container { width: min(var(--container), calc(100% - 36px)); }
  .section { padding: 78px 0; }
  .section-heading { grid-template-columns: 1fr; gap: 18px; margin-bottom: 34px; }
  .section-heading > p { max-width: 600px; }
  .topbar-inner { min-height: 32px; }
  .topbar-status { display: none; }
  .topbar-links { width: 100%; justify-content: space-between; }
  .navbar { min-height: 68px; gap: 12px; }
  .nav-toggle { display: inline-flex; order: 3; }
  .header-cta { order: 2; }
  .site-nav { position: absolute; top: calc(100% + 1px); left: 0; right: 0; display: grid; gap: 0; max-height: 0; padding: 0 20px; overflow: hidden; visibility: hidden; opacity: 0; background: var(--ink); border: 1px solid var(--line-dark); border-radius: 0 0 10px 10px; transition: max-height .25s, opacity .2s, padding .25s, visibility .25s; }
  .nav-open .site-nav { max-height: 420px; padding: 12px 20px 20px; visibility: visible; opacity: 1; }
  .site-nav a { padding: 12px 0; border-bottom: 1px solid var(--line-dark); font-size: .8rem; }
  .site-nav a:last-child { border-bottom: 0; }
  .site-nav a::after { display: none; }
  .hero-inner { min-height: auto; grid-template-columns: 1fr; gap: 52px; padding-top: 70px; padding-bottom: 64px; }
  .hero-copy { max-width: 680px; }
  .hero h1 { max-width: 700px; }
  .hero-visual { width: min(680px, 100%); margin-left: auto; }
  .hero-photo img { height: 480px; }
  .precision-item { padding: 16px; }
  .precision-item span { display: none; }
  .gallery-grid { grid-auto-rows: 210px; }
  .social-card { align-items: flex-start; flex-direction: column; padding: 28px; }
  .project-card, .project-card:nth-child(n) { grid-column: span 6; grid-row: span 1; }
  .project-card:nth-child(1) { grid-column: span 12; grid-row: span 2; }
  .process-grid { grid-template-columns: repeat(2, 1fr); gap: 38px 0; }
  .process-step:nth-child(2)::after { display: none; }
  .values-inner { grid-template-columns: 1fr; gap: 44px; padding-top: 78px; padding-bottom: 78px; }
  .values-copy { max-width: 620px; }
  .faq-layout { grid-template-columns: 1fr; gap: 34px; }
  .faq-intro { position: static; max-width: 600px; }
  .quote-layout { grid-template-columns: 1fr; gap: 42px; }
  .quote-copy { max-width: 650px; }
  .footer-main { grid-template-columns: 1.2fr .8fr; gap: 44px; }
  .footer-contact-col { grid-column: 1 / -1; }
  .footer-contact { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 600px) {
  .container { width: min(var(--container), calc(100% - 28px)); }
  .section { padding: 64px 0; }
  .topbar { font-size: .63rem; }
  .topbar-links { gap: 12px; }
  .topbar-links span { display: none; }
  .brand-tagline { display: none; }
  .brand-copy { gap: 0; }
  .brand-mark { width: 36px; height: 36px; }
  .brand-name { font-size: 1rem; }
  .header-cta { min-height: 38px; padding: 9px 11px; font-size: .65rem; }
  .header-cta .icon { display: none; }
  .nav-toggle { width: 40px; height: 40px; }
  .hero-inner { padding-top: 56px; gap: 42px; }
  .hero h1 { font-size: clamp(2.75rem, 14vw, 4rem); }
  .hero-lead { font-size: .88rem; }
  .hero-actions { display: grid; }
  .hero-actions .btn { width: 100%; }
  .hero-assurances { gap: 12px 18px; margin-top: 28px; font-size: .66rem; }
  .hero-visual { padding: 0 0 26px 12px; }
  .hero-photo img { height: 360px; }
  .hero-note { width: 175px; padding: 15px; }
  .hero-note .icon { margin-bottom: 10px; }
  .precision-grid { grid-template-columns: 1fr; padding: 8px 0; }
  .precision-item { min-height: 56px; justify-content: flex-start; border-right: 0; border-bottom: 1px solid rgba(23,29,34,.14); }
  .precision-item:last-child { border-bottom: 0; }
  .precision-item span { display: block; }
  .services-grid { grid-template-columns: 1fr; }
  .service-card { min-height: 280px; padding: 26px; }
  .gallery-grid { display: grid; grid-template-columns: 1fr; grid-auto-rows: 280px; }
  .project-card, .project-card:nth-child(n) { grid-column: auto; grid-row: auto; }
  .gallery-note { line-height: 1.6; }
  .social-section { padding-bottom: 64px; }
  .social-card { gap: 24px; padding: 24px; }
  .social-profile { align-items: flex-start; gap: 15px; }
  .social-logo { width: 58px; height: 58px; }
  .social-actions { display: grid; width: 100%; }
  .lightbox-close { right: 0; }
  .process-grid { grid-template-columns: 1fr; gap: 34px; }
  .process-step { padding-right: 0; }
  .process-step:not(:last-child) { margin-right: 0; }
  .process-step::after { display: none; }
  .values-inner { padding-top: 64px; padding-bottom: 64px; }
  .quote-form { grid-template-columns: 1fr; padding: 24px; }
  .form-field--full { grid-column: auto; }
  .form-privacy, .form-status { grid-column: auto; }
  .quote-section::after { font-size: 11rem; bottom: -60px; }
  .journal-section { padding: 64px 0; }
  .archive-header { padding: 54px 0 40px; }
  .blog-posts.post-grid { grid-template-columns: 1fr; }
  .post-single-header { padding: 30px 24px 26px; }
  .post-body { padding: 32px 24px; font-size: .9rem; }
  .post-labels-footer { padding: 0 24px 30px; }
  .article-cta { align-items: stretch; flex-direction: column; margin: 0 24px 30px; }
  .comments { padding: 26px 22px; }
  .footer-main { grid-template-columns: 1fr; gap: 36px; padding-top: 54px; }
  .footer-contact-col { grid-column: auto; }
  .footer-contact { grid-template-columns: 1fr; }
  .footer-bottom { align-items: flex-start; flex-direction: column; justify-content: center; gap: 4px; padding: 18px 0 84px; }
  .whatsapp-float { right: 14px; bottom: 14px; width: 52px; height: 52px; padding: 0; justify-content: center; }
  .whatsapp-float span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
}
/* Arabe : police, direction RTL et détails physiques du layout. */
html[dir='rtl'] body { font-family: 'Noto Sans Arabic', Arial, sans-serif; }
html[dir='rtl'] h1, html[dir='rtl'] h2, html[dir='rtl'] h3, html[dir='rtl'] h4,
html[dir='rtl'] .eyebrow, html[dir='rtl'] .brand-tagline { letter-spacing: 0; }
html[dir='rtl'] .hero h1 { line-height: 1.25; }
html[dir='rtl'] .section-heading h2, html[dir='rtl'] .quote-copy h2, html[dir='rtl'] .values-copy h2, html[dir='rtl'] .faq-intro h2 { line-height: 1.4; }
html[dir='rtl'] .hero-lead { line-height: 2; }
html[dir='rtl'] .brand { margin-right: 0; margin-left: auto; }
html[dir='rtl'] .brand-name, html[dir='rtl'] .service-number { direction: ltr; unicode-bidi: isolate; }
html[dir='rtl'] .topbar a[href^='tel'], html[dir='rtl'] .quote-contact a[href^='tel'], html[dir='rtl'] .footer-contact a[href^='tel'] { direction: ltr; unicode-bidi: isolate; }
html[dir='rtl'] .site-nav a::after { left: auto; right: 100%; }
html[dir='rtl'] .site-nav a:hover::after { left: auto; right: 0; }
html[dir='rtl'] .hero-visual { padding-left: 0; padding-right: 28px; }
html[dir='rtl'] .hero-visual::before { left: auto; right: 0; }
html[dir='rtl'] .hero-note { right: auto; left: -18px; }
html[dir='rtl'] .hero-photo figcaption { left: auto; right: 22px; }
html[dir='rtl'] .project-card { text-align: right; }
html[dir='rtl'] .project-caption { left: 58px; right: 22px; }
html[dir='rtl'] .project-zoom { left: 18px; right: auto; }
html[dir='rtl'] .lightbox-close { left: -12px; right: auto; }
html[dir='rtl'] .process-step { padding-right: 0; padding-left: 28px; }
html[dir='rtl'] .process-step:not(:last-child) { margin-right: 0; margin-left: 28px; }
html[dir='rtl'] .process-step::before { left: auto; right: 0; }
html[dir='rtl'] .process-step::after { left: 0; right: 9px; }
html[dir='rtl'] .faq-item summary { padding: 24px 0 24px 50px; }
html[dir='rtl'] .faq-item summary::before, html[dir='rtl'] .faq-item summary::after { left: 5px; right: auto; }
html[dir='rtl'] .faq-answer { padding: 0 0 24px 44px; }
html[dir='rtl'] .comments .avatar-image-container { float: right; margin-right: 0; margin-left: 12px; }
html[dir='rtl'] .comments .comment-block { margin-left: 0; margin-right: 50px; }
html[dir='rtl'] .item-control { float: left; }
@media (max-width: 1080px) {
  html[dir='rtl'] .hero-note { right: auto; left: 0; }
  html[dir='rtl'] .header-cta { margin-left: 0; margin-right: 4px; }
}
@media (max-width: 600px) {
  .header-cta { display: none; }
  .preferences { gap: 5px; }
  .theme-toggle { width: 38px; height: 38px; }
  .language-select { width: 52px; height: 38px; padding: 0 5px; }
  html[dir='rtl'] .hero-visual { padding-left: 0; padding-right: 12px; }
  html[dir='rtl'] .lightbox-close { left: 0; right: auto; }
  html[dir='rtl'] .process-step { padding-left: 0; }
  html[dir='rtl'] .process-step:not(:last-child) { margin-left: 0; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
  html[data-motion='ready'] [data-reveal], html[data-motion='ready'] [data-reveal-item='true'] { opacity: 1 !important; }
  .scroll-progress { display: none; }
  .hero-photo:hover img { transform: none; }
}
@media print {
  .topbar, .site-header, .whatsapp-float, .quote-section, .site-footer, .hero-actions, .blog-pager, .comments, .scroll-progress { display: none !important; }
  [data-reveal], [data-reveal-item] { opacity: 1 !important; }
  body { background: #fff; color: #000; }
  .hero { background: #fff; color: #000; }
  .hero-inner { min-height: auto; }
  .section, .journal-section { padding: 30px 0; }
}
